309	Let $A = \{A^x_a\}$ and $B = \{B^x_a\}$ be two measurements.
310	Then
311	\begin{equation*}
312	A^x_a \ot I \simeq_{\delta} I \ot B^x_a
313	\end{equation*}
314	if and only if
315	\begin{equation*}
316	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot B^{\bx}_a \ket{\psi} \geq 1 - \delta.
317	\end{equation*}
318	\end{proposition}
319	\begin{proof}
320	We compute
321	\begin{align*}
322	&\E_{\bx} \sum_{a \neq b}\bra{\psi} A^{\bx}_a \ot B^{\bx}_b \ket{\psi}\\
323	=~& \E_{\bx} \sum_b \bra{\psi} \Big(\sum_{a \neq b} A^{\bx}_a\Big) \ot B^{\bx}_b\ket{\psi}\\
324	=~&\E_{\bx} \sum_b \bra{\psi} (I - A^{\bx}_b) \ot B^{\bx}_b\ket{\psi}
325		\tag{because~$A$ is a measurement}\\
326	=~&\E_{\bx} \sum_b \bra{\psi} I \ot B^{\bx}_b\ket{\psi}
327		- \E_{\bx} \sum_b \bra{\psi} A^{\bx}_b \ot B^{\bx}_b\ket{\psi}\\
328	=~&1
329		- \E_{\bx} \sum_b \bra{\psi} A^{\bx}_b \ot B^{\bx}_b\ket{\psi}. \tag{because~$B$ is a measurement}
330	\end{align*}
331	Hence, the first expression is at most~$\delta$ if and only if the last one is as well,
332	and we are done.
333	\end{proof}
